# -*- coding: utf-8 -*-
"""一次性：产出缺口 key 的 8 语机翻分片 locale/mt/gap/<loc>.json。

- key 精确取自 locale/_gap_keys.txt（i18n_audit 扫描去重输出，json 每行一条），
  与运行时 tr() 查表 key 严格一致（含整段 BBCode blob 的换行/制表符）。
- 译文按 _gap_keys.txt 行序对位（1~62）。
- 写盘前逐条校验：占位符 %s/%d 数、BBCode 标签数、换行数与 key 一致
  （与 export_loc.py/check_mt.py 同口径），任一不一致即失败退出。
- zh_CN=key 同文（表格侧登记时写入）；zh_TW 由 fill_loc.py 走 OpenCC s2twp，不在本步。

用法：py -3.14 -X utf8 tools/build_gap_mt.py
"""
import json
import re
import sys
from pathlib import Path

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8")

ROOT = Path(__file__).resolve().parents[1]
KEYS_FILE = ROOT / "locale" / "gap_keys.txt"
OUT_DIR = ROOT / "locale" / "mt" / "gap"

PH = re.compile(r"%(?![%d])[sd]")
TAG = re.compile(r"\[/?[a-z_]+[^\]]*")

