def main():
    keys = [json.loads(line) for line in KEYS_FILE.read_text(encoding="utf-8").splitlines() if line.strip()]
    print(f"key 共 {len(keys)} 条")
    bad_all = False
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    for loc, arr in TRANS.items():
        if len(arr) != len(keys):
            print(f"✗ {loc}: 译文 {len(arr)} 条 != key {len(keys)} 条")
            bad_all = True
            continue
        bad = 0
        for k, v in zip(keys, arr):
            if len(PH.findall(k)) != len(PH.findall(v)):
                print(f"  ✗ [{loc}] 占位符不一致: {k[:40]!r}")
                bad += 1
            kt = TAG.findall(k)
            if kt and len(kt) != len(TAG.findall(v)):
                print(f"  ✗ [{loc}] BBCode 标签数不一致: {k[:40]!r}")
                bad += 1
            if k.count("\n") != v.count("\n"):
                print(f"  ✗ [{loc}] 换行数不一致: {k[:40]!r}")
                bad += 1
        out = OUT_DIR / f"{loc}.json"
        out.write_text(json.dumps(dict(zip(keys, arr)), ensure_ascii=False, indent=1), encoding="utf-8")
        print(f"{loc}: {'✗ ' + str(bad) + ' 条不匹配' if bad else '✓'} → {out.name}（{len(arr)} 条）")
        bad_all = bad_all or bad > 0
    sys.exit(1 if bad_all else 0)


if __name__ == "__main__":
    main()
